$scenario('remote_429_counts_as_real_failure',function()use($pdo,$reset,$assert){$reset();$r=new QueueCoreRepository($pdo);$id=$r->enqueue(new QueueJob(1,1,'order_exact','order','429','normal',0,'remote-429','v1','test',null,['order_id'=>'429'],[],2,null,'operational'));$registry=new QueueHandlerRegistry();$registry->register('order_exact',new class($r) implements QueueHandler{public function __construct(private QueueCoreRepository $repository){}public function handle(QueueClaim $job,QueueExecutionContext $context):QueueResult{$this->repository->physicalTransportStarted($job,$context->attemptId,'GET','/orders/429');$this->repository->responseKnown($job,$context->attemptId,429);throw new App\Services\ApiRhythmDeferredException('remote 429',gmdate('Y-m-d H:i:s'),'retry_after',true);}});$runner=new QueueRunner($r,$registry);for($i=0;$i<2;$i++){$runner->run(new QueueRunRequest('test','remote-429-'.$i,1,microtime(true)+10,30,[],['order_exact'],1,null,'operational',$id));}$row=$r->job($id);$assert(($row['state']??'')==='dead'&&(int)($row['attempt_count']??0)===2&&(int)($row['last_http_status']??0)===429,'known remote 429 did not consume the real failure budget '.json_encode(['state'=>$row['state']??null,'attempts'=>$row['attempt_count']??null,'status'=>$row['last_http_status']??null]));$pdo->prepare('UPDATE queue_core_jobs SET updated_at=DATE_SUB(UTC_TIMESTAMP(3),INTERVAL 61 SECOND) WHERE id=?')->execute([$id]);$assert($r->reviveExhaustedTransient($id,'order_exact','v1',1,1)&&($r->job($id)['state']??'')==='pending','dead transient 429 was not revivable under the same FIFO identity');});
$scenario('handler_deadlines_never_exhaust_failure_budget',function()use($pdo,$reset,$assert){
    $cases=[];
    $cases['fresh_orders_discovery']=static function(QueueCoreRepository $r)use($pdo):QueueHandler{
        $gateway=new class implements FreshOrdersGateway{public int $calls=0;public function fetch(int $c,int $a,string $f,string $t,?string $cursor,int $limit):array{$this->calls++;throw new RuntimeException('deadline handler called gateway');}};
        return new class(new FreshOrdersDiscoveryHandler($pdo,$r,$gateway)) implements QueueHandler{public function __construct(private QueueHandler $inner){}public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return $this->inner->handle($j,new QueueExecutionContext($c->attemptId,microtime(true)-1,$c->launcher));}};
    };
    $cases['order_exact']=static function(QueueCoreRepository $r):QueueHandler{
        $inner=new OrderExactHandler(static fn():OrderSyncService=>throw new RuntimeException('deadline handler built sync'));
        return new class($inner) implements QueueHandler{public function __construct(private QueueHandler $inner){}public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return $this->inner->handle($j,new QueueExecutionContext($c->attemptId,microtime(true)-1,$c->launcher));}};
    };
    foreach($cases as $type=>$factory){
        $reset();$r=new QueueCoreRepository($pdo);
        $payload=$type==='order_exact'?['order_id'=>'70001']:['from'=>'2026-08-01 00:00:00','to'=>'2026-08-02 00:00:00','generation'=>0,'limit'=>20];
        $id=$r->enqueue(new QueueJob(1,1,$type,$type==='order_exact'?'order':'orders_window',$type==='order_exact'?'70001':null,'fresh_orders',0,'deadline-'.$type,'v1','test',null,$payload,[],1,null,'operational'));
        $registry=new QueueHandlerRegistry();$registry->register($type,$factory($r));$runner=new QueueRunner($r,$registry);
        for($i=0;$i<5;$i++){
            $runner->run(new QueueRunRequest('test','deadline-'.$type.'-'.$i,1,microtime(true)+10,30,[],[$type],1,null,'operational',$id));
            $pdo->prepare('UPDATE queue_core_jobs SET next_attempt_at=UTC_TIMESTAMP(3),available_at=UTC_TIMESTAMP(3) WHERE id=?')->execute([$id]);
        }
        $row=$r->job($id);$assert(($row['state']??'')==='retry_wait'&&(int)($row['attempt_count']??-1)===0,"$type deadline exhausted its failure budget");
    }
});
