    foreach(['PAUSE_MELI_API','PAUSE_ERP_AUTOMATION'] as $markerName){
        $reset();$enableFakeApi();$marker=dirname(__DIR__).'/'.$markerName;@unlink($marker);
        $transport=new class($marker) implements MeliHttpTransportInterface{public int $calls=0;public function __construct(private string $marker){}public function request(string $method,string $url,array $data,array $headers,bool $form,array $timeouts):array{$path=(string)(parse_url($url,PHP_URL_PATH)?:'/');App\QueueCore\QueueCoreDispatchFence::beforeTransport($method,$path);App\QueueCore\QueueCoreDispatchFence::transportStarted($method,$path);file_put_contents($this->marker,'race');try{App\QueueCore\QueueCoreDispatchFence::immediatelyBeforeCurl($method,$path);$this->calls++;}finally{@unlink($this->marker);}return ['status'=>200,'body'=>[],'headers'=>[],'curl_error'=>'','duration_ms'=>1,'wire_bytes'=>2,'decoded_bytes'=>2];}};
        $r=new QueueCoreRepository($pdo);$id=$r->enqueue(new QueueJob(1,1,'fresh_orders_discovery','orders_window',null,'fresh_orders',0,'race-'.$markerName,'v1','test',null,[],[],1,null,'operational'));
        $registry=new QueueHandlerRegistry();$registry->register('fresh_orders_discovery',new class($transport) implements QueueHandler{public function __construct(private MeliHttpTransportInterface $transport){}public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{(new MeliApiClient($j->meliAccountId,$this->transport))->get('/orders/search',[],['job_type'=>'fresh_orders_discovery']);return QueueResult::completed();}});
        (new QueueRunner($r,$registry))->run(new QueueRunRequest('cron_v4','race-'.$markerName,1,microtime(true)+10,30,[],['fresh_orders_discovery'],1,null,'operational',$id));
        $row=$r->job($id);$budget=(int)$pdo->query('SELECT COALESCE(SUM(request_count),0) FROM api_budget_windows')->fetchColumn();$rhythm=(int)$pdo->query('SELECT COALESCE(SUM(calls_in_block),0) FROM api_rhythm_states')->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM api_remote_permits WHERE status<>'released'")->fetchColumn();$assert($transport->calls===0&&($row['dispatch_state']??'')==='NOT_DISPATCHED'&&($row['state']??'')==='retry_wait'&&(int)($row['attempt_count']??-1)===0&&$budget===0&&$rhythm===0&&$active===0,$markerName.' race crossed HTTP or leaked a permit '.json_encode(['calls'=>$transport->calls,'dispatch'=>$row['dispatch_state']??null,'state'=>$row['state']??null,'attempts'=>$row['attempt_count']??null,'budget'=>$budget,'rhythm'=>$rhythm,'active'=>$active,'error'=>$row['last_error_class']??null]));
    }
});
$scenario('metrics_windows_truthful',function()use($pdo,$reset,$assert,$job,$request){$reset();$r=new QueueCoreRepository($pdo);$id=$r->enqueue($job(1,'local','metrics-noop'));$claim=$r->claimNext($request('metrics'),['test_work']);$attempt=$r->beginAttempt($claim,'test');$r->finish($claim,$attempt,QueueResult::completed(0));$reservedId=$r->enqueue($job(1,'normal','metrics-reserved'));$reserved=$r->claimNext($request('metrics-reserved'),['test_work']);$reservedAttempt=$r->beginAttempt($reserved,'test');$assert($reserved?->id===$reservedId&&$r->reserveTransport($reserved,$reservedAttempt));$snapshot=(new QueueMetricsService($pdo))->snapshot();$assert(isset($snapshot['window_60m'],$snapshot['current_depth'],$snapshot['cumulative'])&&$snapshot['window_60m']['dispatch_reserved']===1&&$snapshot['window_60m']['physical_http_started']===0&&$snapshot['window_60m']['completed_jobs']===1&&$snapshot['window_60m']['resources_persisted']===0&&$snapshot['last_resource_persisted_at']===null&&$snapshot['last_source_closed_at']!==null);});

