$scenario('eight_day_gap_recovery',function()use($pdo,$reset,$assert){$reset();$pdo->exec("INSERT INTO meli_orders(meli_account_id,external_order_id,date_created,status,synced_at) VALUES(1,'old-gap',DATE_SUB(UTC_TIMESTAMP(),INTERVAL 8 DAY),'paid',UTC_TIMESTAMP())");$repository=new QueueCoreRepository($pdo);$producer=new FreshOrdersProducer($pdo,$repository,300,86400,86400);$windows=[];$gateway=new class($windows) implements FreshOrdersGateway{public array $windows=[];public function __construct(array &$windows){$this->windows=&$windows;}public function fetch(int $c,int $a,string $f,string $t,?string $cursor,int $limit):array{$this->windows[]=[$f,$t];return ['orders'=>[],'next_cursor'=>null,'has_more'=>false,'http_status'=>200,'response_count_state'=>'complete','paging_offset'=>(int)($cursor??0),'paging_total'=>0,'received_count'=>0];}};$registry=new QueueHandlerRegistry();$registry->register('fresh_orders_discovery',new FreshOrdersDiscoveryHandler($pdo,$repository,$gateway));$runner=new QueueRunner($repository,$registry);for($i=0;$i<12;$i++){$producer->scheduleDueAccounts(100);$runner->run(new QueueRunRequest('test','gap-'.$i,1,microtime(true)+20,30,[],['fresh_orders_discovery'],1,null,'operational'));$cp=$pdo->query("SELECT watermark_at FROM queue_core_producer_checkpoints WHERE producer_key='fresh_orders' AND meli_account_id=1")->fetchColumn();if(is_string($cp)&&(strtotime($cp.' UTC')?:0)>=time()-60)break;}$assert(count($gateway->windows)>=8,'bounded windows did not recover the eight-day gap: '.count($gateway->windows));$first=strtotime($gateway->windows[0][0].' UTC')?:PHP_INT_MAX;$latest=(int)$pdo->query("SELECT UNIX_TIMESTAMP(MAX(date_created)) FROM meli_orders WHERE meli_account_id=1")->fetchColumn();$noGap=true;for($i=1;$i<count($gateway->windows);$i++){$previousTo=strtotime($gateway->windows[$i-1][1].' UTC')?:0;$currentFrom=strtotime($gateway->windows[$i][0].' UTC')?:PHP_INT_MAX;if($currentFrom>$previousTo)$noGap=false;}$lastTo=strtotime($gateway->windows[arr