$scenario('manual_explicit_attempt_reopens_terminal_without_duplicate',function()use($pdo,$reset,$assert){$reset();$r=new QueueCoreRepository($pdo);$version=str_repeat('a',64);$attemptA=str_repeat('1',64);$attemptB=str_repeat('2',64);$make=static function(string $attempt)use($version):QueueJob{return new QueueJob(1,1,'manual_exact','orders_sync','7','local',0,ManualQueueLauncher::idempotencyKey(1,1,'orders_sync','7',$version,$attempt),$version,'manual_web',null,['explicit_attempt_key'=>$attempt],[],1,null,'manual');};$first=$r->enqueue($make($attemptA));$registry=new QueueHandlerRegistry();$registry->register('manual_exact',new class implements QueueHandler{public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return QueueResult::review('manual_fixture_review');}});(new QueueRunner($r,$registry))->run(new QueueRunRequest('manual','first-review',1,microtime(true)+10,30,[],['manual_exact'],1,null,'manual',$first));$second=$r->enqueue($make($attemptB));$duplicate=$r->enqueue($make($attemptB));$registry2=new QueueHandlerRegistry();$registry2->register('manual_exact',new class implements QueueHandler{public function handle(QueueClaim $j,QueueExecutionContext $c):QueueResult{return QueueResult::completed(1,1);}});(new QueueRunner($r,$registry2))->run(new QueueRunRequest('manual','second-click',1,microtime(true)+10,30,[],['manual_exact'],1,null,'manual',$second));$assert($first!==$second&&$second===$duplicate&&($r->job($first)['state']??'')==='review'&&($r->job($second)['state']??'')==='completed'&&(int)$pdo->query("SELECT COUNT(*) FROM queue_core_jobs WHERE queue_domain='manual'")->fetchColumn()===2,'explicit retry did not preserve per-click dedupe');});
